import subprocess, base64, os, time, re
log = open('/workspace/auto_servidor.log', 'w')
def run(cmd):
    log.write('\n$ CMD\n')
    r = subprocess.run(cmd, shell=True, capture_output=True, text=True)
    log.write((r.stdout[-1500:] if r.stdout else ''))
    log.write((r.stderr[-800:] if r.stderr else ''))
    log.flush()
    return r

SERVIDOR_B64 = ""
ARRANQUE_B64 = ""

with open('/workspace/servidor_analisis.py', 'wb') as f:
    f.write(base64.b64decode(SERVIDOR_B64))
with open('/workspace/arranque.sh', 'wb') as f:
    f.write(base64.b64decode(ARRANQUE_B64))
log.write('archivos escritos OK\n')

run('cd /workspace && python3 -m py_compile servidor_analisis.py && echo SERVIDOR_SINTAXIS_OK')

run('cd /workspace && curl -sL -o cloudflared https://github.com/cloudflare/cloudflared/releases/latest/download/cloudflared-linux-amd64 && chmod +x cloudflared && ./cloudflared --version')

os.chdir('/workspace')
subprocess.Popen('nohup python3 servidor_analisis.py > server.log 2>&1 &', shell=True, start_new_session=True)
time.sleep(5)
run('curl -s http://localhost:8000/salud')

subprocess.Popen('nohup ./cloudflared tunnel --protocol http2 --url http://localhost:8000 > tunnel.log 2>&1 &', shell=True, start_new_session=True)
time.sleep(10)
r = run('grep -o "https://[a-z-]*\.trycloudflare\.com" tunnel.log | head -1')
log.write('\nURL_TUNEL: ' + (r.stdout.strip() if r.stdout else 'NO_ENCONTRADA') + '\n')
log.write('\nFIN_SERVIDOR\n')
log.close()
